"""The classifier of invisible characters (contract v0.11 section 3.4), over the ONE table both the server and the dashboard read: backend/unicode_invisible.json, generated by
scripts/gen_invisible_table.py from the pinned Unicode Character Database lines. This module holds no range of its own and asks neither `unicodedata` nor any regular-expression engine what a
character is: a Python's Unicode version is not a browser's, and the two would disagree at the edge of every release.

  refuse  a character no screen draws and a model can read (the Tags block, bidi overrides, controls, ...): the text is not a draft; the FIRST one is reported (line, column, code point);
  mark    a character that is allowed, counted and shown (a zero-width non-joiner, a soft hyphen, the blank braille cell ...): up to MAX_MARKED in a file;
  more than MAX_MARKED marked: refused too (`too_many`); a refused character wins over the count wherever it is, so the verdict never depends on which comes first.

The text is never changed: `scan` only reads it, and `without_marked` returns a COPY, for the one use that needs it (testing emptiness after taking the marked characters out). Lines count from 1 by
LF; a column counts from 1 in code points (not UTF-16 units: the dashboard counts the same way), which is what the shared fixture tests/data/invisible-fixture.json pins on both sides."""
import bisect
import json
import re
from pathlib import Path

MAX_MARKED = 50
PATH = Path(__file__).with_name('unicode_invisible.json')


def _starts(ranges):
    return [lo for lo, _hi in ranges]


def load(path=PATH):
    """The table as written in the JSON: {unicode_version, refuse, mark, mark_except}, every range [lo, hi] in decimal code points."""
    table = json.loads(Path(path).read_text(encoding='utf-8'))
    return {'unicode_version': table['unicode_version'], 'refuse': [tuple(r) for r in table['refuse']], 'mark': [tuple(r) for r in table['mark']], 'mark_except': list(table['mark_except'])}


def _pattern(ranges):
    return re.compile('[' + ''.join(f'\\U{lo:08x}-\\U{hi:08x}' for lo, hi in ranges) + ']')


TABLE = load()
_REFUSE_STARTS, _MARK_STARTS = _starts(TABLE['refuse']), _starts(TABLE['mark'])
_ANY = _pattern(sorted(TABLE['refuse'] + TABLE['mark']))     # one pass finds every candidate; the classes are told apart per candidate


def _within(ranges, starts, cp):
    i = bisect.bisect_right(starts, cp) - 1
    return i >= 0 and cp <= ranges[i][1]


def kind_of(cp):
    """'refuse', 'mark' or None for a code point (an int)."""
    if _within(TABLE['refuse'], _REFUSE_STARTS, cp):
        return 'refuse'
    return 'mark' if _within(TABLE['mark'], _MARK_STARTS, cp) else None


def _place(text, index):
    line_start = text.rfind('\n', 0, index) + 1
    return text.count('\n', 0, index) + 1, index - line_start + 1


def scan(text):
    """-> {refused, marked, count}. `refused`: None, or {code ("U+XXXX"), code_point, line, column} of the first refused character. `marked`: [{code_point, line, column}] of the first MAX_MARKED marked characters, in order
    (more than that is a refusal anyway, and no list of them is built); `count`: how many marked characters the text holds. The text is only read."""
    marked, count = [], 0
    for found in _ANY.finditer(text):
        cp = ord(found.group())
        if kind_of(cp) == 'refuse':
            line, column = _place(text, found.start())
            return {'refused': {'code': f'U+{cp:04X}', 'code_point': cp, 'line': line, 'column': column}, 'marked': marked, 'count': count}   # a refusal wins over the count: stop at the first
        count += 1
        if count <= MAX_MARKED:
            line, column = _place(text, found.start())
            marked.append({'code_point': cp, 'line': line, 'column': column})
    return {'refused': None, 'marked': marked, 'count': count}


def verdict(text):
    """'refuse' | 'too_many' | 'ok': what the table says of a whole text."""
    result = scan(text)
    if result['refused'] is not None:
        return 'refuse'
    return 'too_many' if result['count'] > MAX_MARKED else 'ok'


def warning(result):
    """The dry run's warning for a scan that is `ok` and holds marked characters, else None (a text that is refused, for a refused character or for more than MAX_MARKED, has nothing to warn about: it is
    refused): {kind, count, kinds: [{code, count}] by code point, where: [{line, column}]}."""
    if result['refused'] is not None or not result['count'] or result['count'] > MAX_MARKED:
        return None
    counts = {}
    for item in result['marked']:
        counts[item['code_point']] = counts.get(item['code_point'], 0) + 1
    return {'kind': 'invisible_characters', 'count': result['count'], 'kinds': [{'code': f'U+{cp:04X}', 'count': n} for cp, n in sorted(counts.items())],
            'where': [{'line': item['line'], 'column': item['column']} for item in result['marked']]}


def blank(text):
    """True when `text` shows nothing: once the marked characters are taken out of a COPY, `str.strip()` leaves nothing (Hermes's own `.strip()` does not remove a zero-width space, so a body of them has nothing to read
    and would be a channel). Every character on which `str.strip()` and the dashboard's `\\s` differ (U+FEFF, U+001C..U+001F, U+0085) is marked or refused first, so both sides agree on a text that reaches this test."""
    return without_marked(text).strip() == ''


def without_marked(text):
    """A COPY of `text` without its marked characters (never the refused ones: a text that holds one is refused before anything is asked of this). For testing emptiness only: the stored text is never changed."""
    return ''.join(c for c in text if kind_of(ord(c)) != 'mark')
